1	package com.example.starter.evidence;
2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.stereotype.Repository;
6	
7	import java.sql.ResultSet;
8	import java.sql.SQLException;
9	import java.time.LocalDateTime;
10	import java.util.List;
11	import java.util.Optional;
12	
13	/**
14	 * 幂等命令日志表访问。command_key 全局唯一，记录只追加。
15	 */
16	@Repository
17	public class CommandLogRepository {
18	
19	    private static final CommandLogRowMapper ROW_MAPPER = new CommandLogRowMapper();
20	
21	    private final JdbcTemplate jdbc;
22	
23	    public CommandLogRepository(JdbcTemplate jdbc) {
24	        this.jdbc = jdbc;
25	    }
26	
27	    /**
28	     * 记录命令首次执行结果；command_key 冲突时抛出 DuplicateKeyException。
29	     */
30	    public void insert(String commandKey, String actorId, String operation, String requestHash,
31	                       int responseStatus, String responseBody, LocalDateTime now) {
32	        jdbc.update("""
33	                        INSERT INTO command_log
34	                            (command_key, actor_id, operation, request_hash, response_status, response_body, created_at)
35	                        VALUES (?, ?, ?, ?, ?, ?, ?)
36	                        """,
37	                commandKey, actorId, operation, requestHash, responseStatus, responseBody, now);
38	    }
39	
40	    /**
41	     * 按命令键查询首次执行记录。
42	     */
43	    public Optional<CommandLog> findByKey(String commandKey) {
44	        List<CommandLog> rows = jdbc.query(
45	                "SELECT * FROM command_log WHERE command_key = ?", ROW_MAPPER, commandKey);
46	        return rows.stream().findFirst();
47	    }
48	
49	    /**
50	     * 幂等命令日志记录。
51	     *
52	     * @param commandKey     幂等命令键
53	     * @param actorId        发起操作人
54	     * @param operation      操作类型
55	     * @param requestHash    请求参数规范化后的 SHA-256
56	     * @param responseStatus 首次执行的 HTTP 状态码
57	     * @param responseBody   首次执行的响应体 JSON
58	     * @param createdAt      首次执行时间（Asia/Shanghai）
59	     */
60	    public record CommandLog(
61	            String commandKey,
62	            String actorId,
63	            String operation,
64	            String requestHash,
65	            int responseStatus,
66	            String responseBody,
67	            LocalDateTime createdAt) {
68	    }
69	
70	    private static final class CommandLogRowMapper implements RowMapper<CommandLog> {
71	        @Override
