        return updated == 1;
    }

    /**
     * 记录第二人确认完成：FIRST_CONFIRMED -> COMPLETED；仅当仍为 FIRST_CONFIRMED 时生效。
     *
     * @return 是否成功（false 表示已被并发事务先行流转）
     */
    public boolean markCompleted(long id, String secondConfirmer, LocalDateTime now) {
        int updated = jdbc.update("""
                        UPDATE move_order
                        SET status = ?, second_confirmer = ?, decided_at = ?, updated_at = ?
                        WHERE id = ? AND status = ?
                        """,
                MoveStatus.COMPLETED.name(), secondConfirmer, now, now,
                id, MoveStatus.FIRST_CONFIRMED.name());
        return updated == 1;
    }

    /**
     * 撤销迁移单：FIRST_CONFIRMED -> CANCELLED；仅当仍为 FIRST_CONFIRMED 时生效。
     *
     * @return 是否成功（false 表示已被并发事务先行流转）
     */
    public boolean markCancelled(long id, String cancelledBy, LocalDateTime now) {
        int updated = jdbc.update("""
                        UPDATE move_order
                        SET status = ?, cancelled_by = ?, decided_at = ?, updated_at = ?
                        WHERE id = ? AND status = ?
                        """,
                MoveStatus.CANCELLED.name(), cancelledBy, now, now,
                id, MoveStatus.FIRST_CONFIRMED.name());
        return updated == 1;
    }

    private static final class MoveOrderRowMapper implements RowMapper<MoveOrder> {
        @Override
        public MoveOrder mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new MoveOrder(
                    rs.getLong("id"),
                    rs.getString("move_key"),
                    rs.getString("request_hash"),
                    rs.getString("applicant_id"),
                    Arrays.asList(rs.getString("evidence_keys").split(",")),
                    rs.getString("source_location"),
                    rs.getString("target_location"),
                    rs.getInt("expected_version"),
                    MoveStatus.valueOf(rs.getString("status")),
                    rs.getString("first_confirmer"),
                    rs.getObject("first_confirmed_at", LocalDateTime.class),
                    rs.getString("second_confirmer"),
                    rs.getString("cancelled_by"),
                    rs.getObject("decided_at", LocalDateTime.class),
                    rs.getObject("created_at", LocalDateTime.class),
                    rs.getObject("updated_at", LocalDateTime.class));
        }
    }
}

package com.example.starter.evidence;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 迁移封签快照表访问。快照只追加、不可变，不提供任何更新语句。
 */
@Repository
public class MoveSealSnapshotRepository {

    private static final SnapshotRowMapper ROW_MAPPER = new SnapshotRowMapper();

    private final JdbcTemplate jdbc;

    public MoveSealSnapshotRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加一件证物的迁移封签快照。
     */
    public void insert(String moveKey, String evidenceKey, String sealNo,
                       String fromLocation, String toLocation,
                       String firstConfirmer, String secondConfirmer, LocalDateTime now) {
        jdbc.update("""
                        INSERT INTO move_seal_snapshot
                            (move_key, evidence_key, seal_no, from_location, to_location,
                             first_confirmer, second_confirmer, snapshot_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                moveKey, evidenceKey, sealNo, fromLocation, toLocation,
                firstConfirmer, secondConfirmer, now);
    }

    /**
     * 按迁移业务键查询全部快照（按写入顺序）。
     */
    public List<MoveSealSnapshot> findByMoveKey(String moveKey) {
        return jdbc.query(
                "SELECT * FROM move_seal_snapshot WHERE move_key = ? ORDER BY id",
                ROW_MAPPER, moveKey);
    }

    /**
     * 按证物业务键查询全部迁移快照（按写入顺序）。
     */
    public List<MoveSealSnapshot> findByEvidenceKey(String evidenceKey) {
        return jdbc.query(
                "SELECT * FROM move_seal_snapshot WHERE evidence_key = ? ORDER BY id",
                ROW_MAPPER, evidenceKey);
    }

    private static final class SnapshotRowMapper implements RowMapper<MoveSealSnapshot> {
        @Override
        public MoveSealSnapshot mapRow(ResultSet rs, int rowNum) throws SQLException {
            return new MoveSealSnapshot(
                    rs.getLong("id"),
                    rs.getString("move_key"),
                    rs.getString("evidence_key"),
                    rs.getString("seal_no"),
                    rs.getString("from_location"),
                    rs.getString("to_location"),
                    rs.getString("first_confirmer"),
                    rs.getString("second_confirmer"),
                    rs.getObject("snapshot_at", LocalDateTime.class));
        }
    }
}

