        assertThat(confirm("dave", moveKey, uniqueKey("CMD")).getResponse().getStatus())
                .isEqualTo(409);
        assertThat(inventory(ctx[0]).get("evidence")).hasSize(2);
        assertThat(inventory(ctx[1]).get("evidence")).isEmpty();
